import React, { useEffect, useState } from "react";
import { v4 as uuidv4 } from 'uuid';

// 1. ADIM: Merkezi tür tanımlamalarını doğru yerden import edin.
// Bu dosyanın 'src/types/index.ts' veya benzer bir yolda olduğundan emin olun.
import { Question, Message, DomainStatus } from './types';

// 2. ADIM: GERÇEK BİLEŞENLERİ DOĞRU YOLDAN IMPORT EDİN.
// Bu, hatanın ana çözümüdür.
import Header from './components/Header';
import ChatPanel from './components/ChatPanel';
import Sidebar from './components/Sidebar';

const App: React.FC = () => {
  // State tanımlamalarında bir değişiklik yok, bunlar doğru.
  const [questions, setQuestions] = useState<Question[]>([]);
  const [currentQuestionId, setCurrentQuestionId] = useState<number | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);
  const [overallScore, setOverallScore] = useState<number>(0);
  const [isLoading, setIsLoading] = useState<boolean>(true);

  // Veri çekme ve başlangıç durumunu ayarlama mantığı.
  useEffect(() => {
    fetch("http://localhost:3001/questions")
      .then((res) => {
        if (!res.ok) {
          throw new Error(`Ağ yanıtı başarısız: ${res.statusText}`);
        }
        return res.json();
      })
      .then((data: Question[]) => {
        if (!Array.isArray(data) || data.length === 0) {
          console.error("Alınan veri geçerli bir dizi değil veya boş.");
          setMessages([{ id: uuidv4(), sender: 'AI', text: "Hata: Değerlendirme soruları yüklenemedi.", type: 'error', question: undefined }]);
          return;
        }

        setQuestions(data);
        const firstQuestion = data[0];
        setCurrentQuestionId(firstQuestion.id);
        
        setMessages([{
          id: uuidv4(),
          sender: 'AI',
          text: 'Hoş geldiniz! Değerlendirmeye başlayalım.',
          type: 'question',
          question: firstQuestion,
        }]);

        const initialDomains: DomainStatus[] = [...new Set(data.map(q => q.domain_name))].map(domainName => ({
          name: domainName,
          status: domainName === firstQuestion.domain_name ? 'In Progress' : 'Pending',
          score: 0,
        }));
        setDomainStatuses(initialDomains);
      })
      .catch((err) => {
        console.error("Soruları çekerken hata:", err);
        setMessages([{ id: uuidv4(), sender: 'AI', text: "Backend'e bağlanılamadı. Lütfen sunucunun çalıştığından emin olun.", type: 'error', question: undefined }]);
      })
      .finally(() => {
        setIsLoading(false);
      });
  }, []);

  // Mesaj gönderme ve state güncelleme mantığının tam hali.
  const handleSendMessage = async (prompt: string) => {
    if (!currentQuestionId || isLoading) return;
    setIsLoading(true);

    const userMessage: Message = { id: uuidv4(), sender: 'User', text: prompt, type: 'user_response' };
    setMessages(prev => [...prev, userMessage]);

    try {
      const res = await fetch("http://localhost:3001/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ prompt, previous_question_id: currentQuestionId }),
      });
      if (!res.ok) { throw new Error(`API hatası: ${res.statusText}`); }
      const apiResponse = await res.json();
      
      const taskMessage: Message = { id: uuidv4(), sender: 'AI', text: apiResponse.task || "Bir görev oluşturulmadı.", type: 'task_confirmation' };

      const answeredQuestion = questions.find(q => q.id === currentQuestionId);
      const nextQuestion = questions.find(q => q.id === apiResponse.next_question_id);

      // Domain durumlarını ve skorları güncelleme mantığı
      if (answeredQuestion) {
        setDomainStatuses(prevStatuses => {
            const newStatuses = prevStatuses.map(status => {
                let updatedStatus = { ...status };
                
                // 1. Cevaplanan domain'in skorunu ve durumunu güncelle
                if (status.name === answeredQuestion.domain_name) {
                    const domainQuestions = questions.filter(q => q.domain_name === status.name);
                    const questionWeight = 100 / (domainQuestions.length || 1); // Her sorunun domain içindeki ağırlığı
                    const newScore = Math.min(100, status.score + (apiResponse.score / 100) * questionWeight);
                    
                    updatedStatus.score = parseFloat(newScore.toFixed(2));

                    // Eğer bu domain'den sonraki soru yoksa veya sonraki soru farklı bir domaindeyse, bu domain'i 'Complete' yap
                    const isDomainFinished = !nextQuestion || nextQuestion.domain_name !== status.name;
                    if(isDomainFinished) {
                        updatedStatus.status = 'Complete';
                    }
                }

                // 2. Bir sonraki domain'i 'In Progress' olarak işaretle
                if (nextQuestion && status.name === nextQuestion.domain_name && status.status === 'Pending') {
                    updatedStatus.status = 'In Progress';
                }

                return updatedStatus;
            });

            // 3. Genel skoru yeniden hesapla
            const totalScore = newStatuses.reduce((acc, curr) => acc + curr.score, 0);
            setOverallScore(parseFloat((totalScore / (newStatuses.length || 1)).toFixed(2)));
            
            return newStatuses;
        });
      }

      // Bir sonraki mesajları ayarla
      if (nextQuestion) {
        // Test devam ediyor
        const nextQuestionMessage: Message = { id: uuidv4(), sender: 'AI', text: 'Sıradaki soru:', type: 'question', question: nextQuestion, ai_comment: apiResponse.comment };
        setMessages(prev => [...prev, taskMessage, nextQuestionMessage]);
        setCurrentQuestionId(apiResponse.next_question_id);
      } else {
        // Test bitti
        const endMessage: Message = { id: uuidv4(), sender: 'AI', text: '🎉 Değerlendirme tamamlandı! Yanıtlarınız için teşekkür ederiz.', type: 'question', question: undefined };
        setMessages(prev => [...prev, taskMessage, endMessage]);
        setCurrentQuestionId(null);
      }
    } catch (err) {
      console.error("Mesaj gönderilirken hata:", err);
      setMessages(prev => [...prev, { id: uuidv4(), sender: 'AI', text: "İsteğiniz işlenirken bir hata oluştu.", type: 'error', question: undefined }]);
    } finally {
      setIsLoading(false);
    }
  };

  // 3. ADIM: Render edilecek JSX, doğru proplarla bileşenleri çağırır.
  return (
    <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen overflow-hidden flex flex-col">
      <Header />
      <div className="flex flex-1 overflow-hidden">
        <ChatPanel messages={messages} onSendMessage={handleSendMessage} isLoading={isLoading} />
        <Sidebar statuses={domainStatuses} overallScore={overallScore} />
      </div>
    </div>
  );
};

export default App;
